/// <summary>
/// Extension Class for WhsControlItemId
/// </summary>
[
    ExtensionOf(classStr(WhsControlItemId))
]
final class NDXWhsControlItemId_Cls_Extension
{
}

Method.Source:
/// <summary>
/// Extension Methode for process()
/// </summary>
/// <returns>
/// Return true if check valid otherwise false
/// </returns>
public boolean process()
{
    boolean avaValid;

    avaValid = next process();
    avaValid = avaValid && this.avaProcess();

    return avaValid;
}

/// <summary>
/// Rooting Methode for other item Checks
/// </summary>
/// <returns>
/// Return true if check valid otherwise false
/// </returns>
public boolean avaProcess()
{
    boolean avaValid;

    avaValid = true;
    avaValid = avaValid && this.avaCheckItemSet();

    return avaValid;
}

/// <summary>
/// Check if item marked as set. If set and AdjustmentIn process return false
/// </summary>
/// <returns>
/// Return true if check valid otherwise false
/// </returns>
public boolean avaCheckItemSet()
{
    boolean         avaValid;
    InventTable     avaInventTable;

    avaValid = true;

    if (mode == WHSWorkExecuteMode::AdjustmentIn
     || mode == WHSWorkExecuteMode::SpotCycleCounting
     || mode == WHSWorkExecuteMode::CycleCounting
     || mode == WHSWorkExecuteMode::CycleCountGrouping
     || mode == WHSWorkExecuteMode::CycleCountingReview)
    {
        avaInventTable = InventTable::find(fieldValues.parmItemId());

        if (avaInventTable
         && avaInventTable.AVAItemSet == NoYes::Yes)
        {
            fieldValues.parmItemId('');
            avaValid = this.fail("@NDX:NoItemSetInAdjustmentIn");
        }
    }

    return avaValid;
}

/// <summary>
/// checkItemIdWorkExecuteMode
/// </summary>
/// <returns>boolean</returns>
protected boolean checkItemIdWorkExecuteMode()
{
    boolean ret = next checkItemIdWorkExecuteMode();

    if (ret && mode == WHSWorkExecuteMode::AVAWHSreceivingSO)
    {
        ret = false;
    }

    return ret;
}
